#!/usr/bin/env node
// Gives the Xcode project generated by convert.sh the version numbers of the
// extension build it wraps.
//
//   node safari/xcode/set-version.mjs <extension-dir> <project.xcodeproj>
//
// Apple's converter writes version 1.0 (build 1) into every project. With the
// same numbers on every build, macOS has no way to prefer a newer copy of the
// app over an older one that is still on the disk, and Safari may keep loading
// the extension of the old copy. The app therefore gets
//   - the extension's version (its first three parts) as its version, and
//   - the build number from safari-build.json, which grows with every build.

import fs from 'node:fs';
import path from 'node:path';

const [extDir, project] = process.argv.slice(2);
if (!extDir || !project) {
  console.error('usage: set-version.mjs <extension-dir> <project.xcodeproj>');
  process.exit(2);
}

const info = JSON.parse(fs.readFileSync(path.join(extDir, 'safari-build.json'), 'utf8'));
const version = String(info.version).split('.').slice(0, 3).join('.');
const build = String(info.build && info.build.number);
// Both must be one to three integers separated by periods.
for (const [name, value] of [['version', version], ['build number', build]]) {
  if (!/^\d+(\.\d+){0,2}$/.test(value) || value.length > 18) {
    console.error(`error: ${name} ${JSON.stringify(value)} is not usable as an app version`);
    process.exit(1);
  }
}

const file = path.join(project, 'project.pbxproj');
let replaced = 0;
const text = fs.readFileSync(file, 'utf8').replace(/\b(MARKETING_VERSION|CURRENT_PROJECT_VERSION) = [^;]+;/g, (match, key) => {
  replaced++;
  return `${key} = ${key === 'MARKETING_VERSION' ? version : build};`;
});
if (!replaced) {
  console.error(`error: no version settings found in ${file}`);
  process.exit(1);
}
fs.writeFileSync(file, text);
console.log(`App version ${version}, build ${build} (${replaced} settings in ${path.basename(project)})`);
